function renderProtocols() {
    const grid = document.getElementById('protocolsGrid');
    if (!grid) return;
    grid.innerHTML = '';
    const tagLabels = { 'shoulder-proto':'Shoulder', 'elbow-proto':'Elbow',
                        'hand-proto':'Hand, Forearm & Wrist', 'nonop':'Non-Operative' };
    PROTOCOLS.forEach(p => {
        const card = document.createElement('div');
        card.className = 'resource-card';
        card.dataset.category = p.category;
        card.innerHTML = `
            <span class="card-tag ${p.category}">${tagLabels[p.category] || p.category}</span>
            <h3>${p.title}</h3>
            <p>${p.description}</p>
            <a href="${p.file}" class="card-download" download>
                <i class="fas fa-file-download"></i> Download
            </a>`;
        grid.appendChild(card);
    });
}
document.addEventListener('DOMContentLoaded', renderProtocols);
